int unimac_mdio_probe(struct platform_device *pdev)
{
    struct resource *res;
    void __iomem *base;
    struct mii_bus *bus;
    struct unimac_mdio_priv *priv;
    int ret;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res) {
        ret = -ENODEV;
        goto free_priv;
    }

    base = devm_ioremap_resource(&pdev->dev, res);
    if (IS_ERR(base)) {
        ret = PTR_ERR(base);
        goto free_priv;
    }

    bus = devm_mdiobus_alloc(&pdev->dev);
    if (!bus) {
        ret = -ENOMEM;
        goto free_priv;
    }

    bus->priv = (void *)priv;
    bus->name = "UniMAC MDIO bus";
    bus->read = unimac_mdio_read;
    bus->write = unimac_mdio_write;
    bus->parent = &pdev->dev;

    platform_set_drvdata(pdev, bus);

    ret = of_mdiobus_register(pdev->dev.of_node, bus, &pdev->dev);
    if (ret)
        goto free_priv;

    dev_info(&pdev->dev, "MDIO bus registered at %pR\n", res);
    return 0;

free_priv:
    kfree(priv);
    return ret;
}

int unimac_mdio_probe(struct platform_device *pdev)
{
    struct resource *res;
    void __iomem *base;
    struct mii_bus *bus;
    int ret;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res)
        return -ENODEV;

    base = ioremap(res->start, resource_size(res));
    if (!base)
        return -ENOMEM;

    bus = alloc_mdio_bus(NULL, 0);
    if (!bus) {
        iounmap(base);
        return -ENOMEM;
    }

    bus->priv = base;
    bus->read = mdio_bus_read;
    bus->write = mdio_bus_write;
    bus->name = "UniMAC MDIO Bus";
    snprintf(bus->id, MII_BUS_ID_SIZE, "unimac-mdio.%d", pdev->id);

    ret = mdio_bus_register(bus, &pdev->dev);
    if (ret < 0) {
        free_mdio_bus(bus);
        iounmap(base);
        return ret;
    }

    platform_set_drvdata(pdev, bus);
    dev_info(&pdev->dev, "MDIO bus registered at base address %p\n", base);

    return 0;
}

