int unimac_mdio_probe(struct platform_device *pdev)
{
    struct resource *res;
    void __iomem *base;
    struct mii_bus *bus;
    int ret;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res) {
        dev_err(&pdev->dev, "Failed to get memory resource\n");
        return -ENODEV;
    }

    base = ioremap(res->start, resource_size(res));
    if (!base) {
        dev_err(&pdev->dev, "Failed to ioremap\n");
        return -ENOMEM;
    }

    bus = alloc_mdio_bus(NULL, 0);
    if (!bus) {
        dev_err(&pdev->dev, "Failed to allocate MII bus\n");
        iounmap(base);
        return -ENOMEM;
    }

    bus->name = "UniMAC MDIO Bus";
    bus->read = mdio_bus_read;
    bus->write = mdio_bus_write;
    bus->parent = &pdev->dev;

    ret = mdio_bus_init(bus);
    if (ret < 0) {
        dev_err(&pdev->dev, "Failed to initialize MII bus\n");
        free_mdio_bus(bus);
        iounmap(base);
        return ret;
    }

    ret = mdio_bus_register(pdev, bus);
    if (ret < 0) {
        dev_err(&pdev->dev, "Failed to register MII bus\n");
        free_mdio_bus(bus);
        iounmap(base);
        return ret;
    }

    platform_set_drvdata(pdev, bus);
    dev_info(&pdev->dev, "MDIO Bus base address: %p\n", base);

    return 0;
}

